SET IMPLICIT_TRANSACTIONS OFF;
SET NOCOUNT ON;
INSERT INTO [fx_products] ([Category], [Name], [Price])
OUTPUT INSERTED.[Id]
VALUES (@p0, @p1, @p2);

SET IMPLICIT_TRANSACTIONS OFF;
SET NOCOUNT ON;
MERGE [fx_products] USING (
VALUES (@p0, @p1, @p2, 0),
(@p3, @p4, @p5, 1),
(@p6, @p7, @p8, 2)) AS i ([Category], [Name], [Price], _Position) ON 1=0
WHEN NOT MATCHED THEN
INSERT ([Category], [Name], [Price])
VALUES (i.[Category], i.[Name], i.[Price])
OUTPUT INSERTED.[Id], i._Position;
